#!/bin/bash
# Progressive-scale ladder: load data in stages into ONE database, measuring after each stage.
# usage: scale_ladder.sh OUTDIR   (expects $CV_BENCH/s0 s1 s2 and c1 c2 c3 generated by perfbench generate)
# Each stage: durable importfolder (timed, WAL + size delta) -> VACUUM (ANALYZE) -> queries -> storage
# plus a concurrent import-vs-search run (c1..c3) on the same populated database.
. "${CV_ENV_FILE:-/tmp/pgenv.sh}"
OUT=${1:?outdir}; mkdir -p "$OUT"
ROOT=${CV_ROOT:-/home/user/credvault}; B=${CV_BENCH:-/tmp/bench}
PGB=$ROOT/.venv/lib/python3.11/site-packages/pgserver/pginstall/bin
PSQL="$PGB/psql -h $POSTGRES_HOST -U postgres -q -At -d $POSTGRES_DB"
PY=$ROOT/.venv/bin/python; cd $ROOT
now() { date +%s.%N; }
snap() { $PSQL -c "select pg_database_size(current_database()), pg_current_wal_lsn()"; }
stage() {  # name datadir
  local name=$1 dir=$2
  echo "== stage $name import $(date -Is)"
  local s0=$(snap); local t0=$(now)
  $PY manage.py importfolder $dir > $OUT/${name}_import.txt 2>&1; local rc=$?
  local t1=$(now); local s1=$(snap)
  local lsn0=${s0#*|} lsn1=${s1#*|}
  local wal=$($PSQL -c "select pg_wal_lsn_diff('$lsn1','$lsn0')")
  local acc=$($PSQL -c "select count(*) from vault_account")
  echo "{\"stage\":\"$name\",\"rc\":$rc,\"seconds\":$(python3 -c "print(round($t1-$t0,2))"),\"db_bytes_before\":${s0%|*},\"db_bytes_after\":${s1%|*},\"wal_bytes\":$wal,\"accounts\":$acc}" > $OUT/${name}_import.json
  cat $OUT/${name}_import.json
  $PSQL -c "VACUUM (ANALYZE)"
  $PY manage.py perfbench storage > $OUT/${name}_storage.json 2>$OUT/${name}_storage.err
  $PY manage.py perfbench queries --runs 7 --explain > $OUT/${name}_queries.json 2>$OUT/${name}_queries.err
}
conc() {  # name datadir
  echo "== concurrent $1 $(date -Is)"
  $PY manage.py perfbench concurrent $2 --query-workers 2 > $OUT/$1_concurrent.json 2>$OUT/$1_concurrent.err
  $PSQL -c "VACUUM (ANALYZE)"
}
stage s0 $B/s0
stage s1 $B/s1
conc s1c $B/c1
stage s2 $B/s2
conc s2c $B/c2
echo "== done $(date -Is)"
